            local function Create(class, props, children)
            local obj = Instance.new(class)
            for prop, val in pairs(props) do
                obj[prop] = val
            end
            if children then
                for _, child in ipairs(children) do
                    child.Parent = obj
                end
            end
            return obj
        end

        local function AddShimmer(button, color)
            local shimmer = Create("Frame", {
                Name = "Shimmer",
                Size = UDim2.new(0, 40, 1, 0),
                Position = UDim2.new(-0.2, 0, 0, 0),
                BackgroundColor3 = color or Color3.fromRGB(255, 255, 255),
                BackgroundTransparency = 0.8,
                BorderSizePixel = 0,
                ZIndex = button.ZIndex + 1,
                Parent = button
            }, {
                Create("UIGradient", {
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.5, 0),
                        NumberSequenceKeypoint.new(1, 1)
                    }),
                    Rotation = 15
                })
            })

            task.spawn(function()
                while button and button.Parent do
                    shimmer.Position = UDim2.new(-0.2, 0, 0, 0)
                    local t = TweenService:Create(shimmer, TweenInfo.new(1.5, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut), {
                        Position = UDim2.new(1.2, 0, 0, 0)
                    })
                    t:Play()
                    t.Completed:Wait()
                    task.wait(3)
                end
            end)
        end
        
