                            Position = UDim2.new(0.52, 0, 0, 0)
                        }):Play()
                    end)
                    elements.verifyButton.MouseButton1Down:Connect(function()
                        TweenService:Create(elements.verifyButton, TweenInfo.new(0.1), {
                            Size = UDim2.new(0.47, 0, 0, 38),
