                        }):Play()
                    end)
                    elements.verifyButton.MouseButton1Up:Connect(function()
                        TweenService:Create(elements.verifyButton, TweenInfo.new(0.1), {
                            Size = UDim2.new(0.48, 4, 0, 44),
                            Position = UDim2.new(0.52, -2, 0, -2)
                        }):Play()
                    end)
