                if elements.discordButton then
                    elements.discordButton.MouseEnter:Connect(function()
                        TweenService:Create(elements.discordButton, TweenInfo.new(0.2), {
                            BackgroundColor3 = Color3.fromRGB(115, 105, 255),
                            Size = UDim2.new(0.48, 4, 0, 44),
